import{_ as d,o as r,c as n,af as s}from"./chunks/framework.B28LkSoM.js";const b=JSON.parse('{"title":"2027事业单位备考规划","description":"从零开始备考河南事业单位联考的完整规划：考试结构、目标分数、资源清单、每一步的学习方法，以及报名选岗、专业匹配、考场规则、面试体检考察全流程。","frontmatter":{"title":"2027事业单位备考规划","published":"2026-10-03T00:00:00.000Z","updated":"2026-10-04T00:00:00.000Z","tags":["事业单位","备考","学习路线","学习方法","河南"],"description":"从零开始备考河南事业单位联考的完整规划：考试结构、目标分数、资源清单、每一步的学习方法，以及报名选岗、专业匹配、考场规则、面试体检考察全流程。","date":"2026-10-03T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/回收站🗑️/2027事业单位备考规划.md","filePath":"posts/回收站🗑️/2027事业单位备考规划.md"}'),a={name:"posts/回收站🗑️/2027事业单位备考规划.md"};function o(l,t,i,e,g,h){return r(),n("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1790985600000"},[...t[0]||(t[0]=[s(`<blockquote><p>🔄 <strong>2026-10-20 覆盖说明</strong></p><p>这份是&quot;原理篇&quot;，<strong>第一至第七节（考试结构、目标分数、各模块学习方法、选岗规则、考场规则、面试）全部仍然有效</strong>，是整套文件里最该反复读的部分。</p><p>但下面五处<strong>已被现实推翻，请以新文件为准</strong>：</p><table tabindex="0"><thead><tr><th>这里写的</th><th>现在的事实</th><th>去哪看</th></tr></thead><tbody><tr><td>§3.2「<strong>别买粉笔 680 系统班</strong>，和华图 599 重复」</td><td><strong>已买 680 河南班</strong>，是当前主线；且含 SVIP 18 个月 + AI 刷题班 + 13 册图书，比预想的完整得多</td><td><a href="./2027事业单位备考每日执行清单-v3.html">执行清单 v3</a> 第二节</td></tr><tr><td>§4.2「框架笔记<strong>自己手写</strong> A4 活页、默写三遍」</td><td>改成<strong>讲义三色批注 → 看 AI 课程脉络 → 压缩成自测清单</strong></td><td>同上 第八节</td></tr><tr><td>§7 每日时间表（全纸质、无听课封顶）</td><td>听课<strong>封顶 2.8 小时</strong>（每天 2 讲），知识上平板，作文改错必须纸质</td><td>同上 第七节</td></tr><tr><td>§9「<strong>34 周</strong>逐周计划」（10/5 起）</td><td><strong>32 周</strong>，10/20 起算；且逐周表改为&quot;680 模块驱动&quot;</td><td><a href="./2027事业单位备考单周计划表-v3-W1-W3.html">周表 v3</a></td></tr><tr><td>§4.7「数字推理要单独找课学」</td><td><strong>680 有专门 1 讲</strong>（10/12），外部课不用补</td><td>同上 第四节</td></tr></tbody></table><p>另外：§4.10 大作文、§4.11 公文改错这两节的<strong>方法论述仍然最好用</strong>。680 虽然 12/10–12/16 有 5 讲主观题，但那时才讲太晚，<strong>这周就得开始按 §4.10、§4.11 的方法练手写</strong>。</p></blockquote><p><strong>目标</strong>：2027 年河南省事业单位联考 · 商丘 · 综合类计算机岗 <strong>笔试</strong>：预计 2027 年 5 月下旬　<strong>总分目标</strong>：65 <strong>起止</strong>：2026-10-05（教材到货）— 2027-05-30，共 34 周</p><blockquote><p>这篇是按「完全没接触过公职类考试」的起点写的，所以第四到第六部分（学习方法、报名选岗、考场规则）讲得比较细。考试结构、分数线、招录规模、报名与考试规则全部来自官方公告、官方岗位表和面试名单，不是二手转述。</p><p>⚠️ 写于 2026 年 10 月 3 日、更新于 10 月 4 日，2027 年联考公告尚未发布，时间节点为基于 2023—2026 年四年规律的推测。官方信息以河南省人社厅（hrss.henan.gov.cn）、河南省人事考试中心（hnrsks.com）、商丘人事考试网（sqrsks.cn）为准。</p></blockquote><h2 id="一、考试结构" tabindex="-1">一、考试结构 <a class="header-anchor" href="#一、考试结构" aria-label="Permalink to &quot;一、考试结构&quot;">​</a></h2><h3 id="_1-1-公基-100-分-客观-50-主观-50" tabindex="-1">1.1 公基 100 分 = 客观 50 + 主观 50 <a class="header-anchor" href="#_1-1-公基-100-分-客观-50-主观-50" aria-label="Permalink to &quot;1.1 公基 100 分 = 客观 50 + 主观 50&quot;">​</a></h3><table tabindex="0"><thead><tr><th>题型</th><th>题量 × 分值</th><th>小计</th><th>建议用时</th></tr></thead><tbody><tr><td>单选</td><td>20 × 1</td><td>20</td><td>客观题合计 30 分钟</td></tr><tr><td>多选</td><td>15 × 2</td><td>30</td><td>同上</td></tr><tr><td>改错</td><td>5 × 2</td><td>10</td><td>8 分钟</td></tr><tr><td>写作</td><td>1</td><td>40</td><td>48—50 分钟</td></tr></tbody></table><p><strong>改错题三年换了三种形式，只练一种会直接丢 10 分：</strong></p><table tabindex="0"><thead><tr><th>年份</th><th>形式</th><th>考法</th></tr></thead><tbody><tr><td>2024</td><td>判断改错</td><td>5 个独立句子，找错别字和病句</td></tr><tr><td>2025</td><td>公文改错</td><td>给一篇真实公文，找格式 + 内容错误</td></tr><tr><td>2026</td><td>公文逻辑改错</td><td>题干明确提示「无格式错误」，只找逻辑错误</td></tr></tbody></table><p><strong>写作</strong>：材料作文 / 议论文，40 分，1000 字左右。常是无材料或短材料命题，不能像申论那样抄材料。 已考主题：积累与务实（2023，松鼠埋松果两则寓言）／珍惜时光与奋斗（2024，老者和学生的问卷）／反对形式主义、务实精简（2025，紫色奶牛 + 欧阳修「逸马杀犬于道」）。</p><p><strong>板块权重</strong>：政治（含时政）占三分之一以上 &gt; 法律 &gt; 经济 &gt; 公文 &gt; 职业道德、人文、国情。 <strong>时政范围</strong>：近一年为主，<strong>近半年重中之重</strong>。</p><h3 id="_1-2-职测-100-分-90-分钟-约-100-题" tabindex="-1">1.2 职测 100 分 / 90 分钟 / 约 100 题 <a class="header-anchor" href="#_1-2-职测-100-分-90-分钟-约-100-题" aria-label="Permalink to &quot;1.2 职测 100 分 / 90 分钟 / 约 100 题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模块</th><th>题量</th><th>考场时间</th></tr></thead><tbody><tr><td>言语理解</td><td>30</td><td>25 分钟</td></tr><tr><td>判断推理</td><td>30</td><td>27 分钟</td></tr><tr><td>资料分析</td><td>15</td><td>22 分钟</td></tr><tr><td>常识判断</td><td>10</td><td>5 分钟</td></tr><tr><td>数量关系</td><td>15</td><td>6—8 分钟，只做 2—3 题</td></tr><tr><td>涂卡</td><td>—</td><td>3—5 分钟，做一模块涂一模块</td></tr></tbody></table><p><strong>答题顺序</strong>：言语 → 判断 → 资料 → 常识 → 数量。题干 30 秒没思路立刻放弃。</p><p>河南特色考点：<strong>数字推理 5 题</strong>（国考已取消）、<strong>图形推理 10 题</strong>、<strong>常识判断 10 题</strong>（2025 年新增，与公基重合度高）。 难度定位：比省考简单，但 54 秒一题，是「做不完」型考试，不是「不会做」型。</p><h2 id="二、目标分数" tabindex="-1">二、目标分数 <a class="header-anchor" href="#二、目标分数" aria-label="Permalink to &quot;二、目标分数&quot;">​</a></h2><p><strong>公基 65 = 客观题 35/50（单选 18 + 多选 11）+ 主观题 30/50（改错 8 + 作文 22）</strong></p><table tabindex="0"><thead><tr><th>职测模块</th><th>题量</th><th>目标正确率</th><th>得分</th></tr></thead><tbody><tr><td>言语理解</td><td>30</td><td>80%</td><td>24</td></tr><tr><td>判断推理</td><td>30</td><td>75%</td><td>22.5</td></tr><tr><td>资料分析</td><td>15</td><td>90%</td><td>13.5</td></tr><tr><td>常识判断</td><td>10</td><td>50%</td><td>5</td></tr><tr><td>数量关系</td><td>15</td><td>30%</td><td>4.5</td></tr><tr><td><strong>合计</strong></td><td>100</td><td>—</td><td><strong>69.5</strong></td></tr></tbody></table><p>参考：商丘计算机岗进面最低分中位——2024 年 64.5 / 2025 年 53.95 / 2026 年 60.65。进面是 1:3，笔试面试各占 50%，卡着进面线没用。</p><h2 id="三、教材与资源" tabindex="-1">三、教材与资源 <a class="header-anchor" href="#三、教材与资源" aria-label="Permalink to &quot;三、教材与资源&quot;">​</a></h2><p><strong>已有</strong>：粉笔《公共基础知识》《职业能力测验》教材 + 河南联考纸质真题</p><h3 id="_3-1-免费资源-日常学习主体" tabindex="-1">3.1 免费资源（日常学习主体） <a class="header-anchor" href="#_3-1-免费资源-日常学习主体" aria-label="Permalink to &quot;3.1 免费资源（日常学习主体）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>科目</th><th>跟谁</th><th>平台</th></tr></thead><tbody><tr><td>公基打底</td><td>李梦娇（口诀记忆，适合零基础）</td><td>B站</td></tr><tr><td>公基体系</td><td>马克 Mark《公基 &amp; 常识系统课》86 集</td><td>B站</td></tr><tr><td><strong>时政</strong></td><td><strong>马克 Mark《时政梳理（近一年）》</strong></td><td>B站</td></tr><tr><td>职测入门</td><td>刘文超 Vin</td><td>B站</td></tr><tr><td>言语理解</td><td>郭熙《言语必做 100 题》</td><td>粉笔 / B站</td></tr><tr><td>图形推理</td><td>蔡金龙</td><td>B站</td></tr><tr><td>逻辑判断</td><td>聂佳打基础 → 钩不了沉破瓶颈</td><td>粉笔 / B站</td></tr><tr><td><strong>资料分析</strong></td><td><strong>齐麟 + 花生十三 415 份数法</strong></td><td>B站</td></tr><tr><td><strong>大作文</strong></td><td>醒醒最厉害（结构）+ 鲤成讲公考（河南专项）</td><td>B站</td></tr><tr><td><strong>公文改错</strong></td><td>公考李致（系统课）+ 大林法律（河南专用）</td><td>B站</td></tr><tr><td>真题复盘</td><td>刘浩文 vin、不当行测小白、刀哥公考</td><td>B站</td></tr><tr><td><strong>面试</strong>（笔试后）</td><td>公考李靠谱（河南本土，考官评分标准解读）</td><td>B站</td></tr></tbody></table><h3 id="_3-2-付费买什么" tabindex="-1">3.2 付费买什么 <a class="header-anchor" href="#_3-2-付费买什么" aria-label="Permalink to &quot;3.2 付费买什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>价格</th><th>什么时候买</th></tr></thead><tbody><tr><td>华图 2027 河南事业编系统班【公基+职测+主观题】</td><td>¥599</td><td>现在（11 月下旬开播，图书先寄）</td></tr><tr><td>李梦娇时政（每月初更新上月）</td><td>¥19.9/年</td><td>现在</td></tr><tr><td>半月谈《时政提分宝》</td><td>¥29.8</td><td>现在</td></tr><tr><td>粉笔「职测+综应」会员（AI 批改不限次）</td><td>¥49/月</td><td>11 月起</td></tr><tr><td><strong>人工精批 3—5 次</strong></td><td>约 ¥129/次</td><td>1 月、3 月、4—5 月</td></tr><tr><td>京佳 19 天刷题课（线上，含公文改错专项）</td><td>¥399</td><td>2027 年 1—3 月</td></tr></tbody></table><h2 id="四、学习方法-每一步具体怎么做" tabindex="-1">四、学习方法（每一步具体怎么做） <a class="header-anchor" href="#四、学习方法-每一步具体怎么做" aria-label="Permalink to &quot;四、学习方法（每一步具体怎么做）&quot;">​</a></h2><h3 id="_4-1-听课怎么听" tabindex="-1">4.1 听课怎么听 <a class="header-anchor" href="#_4-1-听课怎么听" aria-label="Permalink to &quot;4.1 听课怎么听&quot;">​</a></h3><p><strong>目标不是「听完」，是「合上书能默写出这一节的骨架」。</strong></p><ul><li>新板块第一遍用原速，熟悉的复习章节可以 1.5 倍速</li><li><strong>不要边听边暂停抄笔记</strong>——课会被切碎，注意力全在抄写上。听完一小节（10—15 分钟）再停笔归纳</li><li>老师举例时只记三个字的关键词，不要抄完整例子</li><li>听不懂的地方立刻打问号，<strong>当天就要解决</strong>，不要留到第二天</li><li>同一节课听两遍很正常。第一遍听结构，第二遍补细节</li><li>李梦娇和马克用法不同：马克用来搭框架（体系完整），李梦娇用来记考点（口诀好背）。<strong>时政单独跟马克</strong></li></ul><h3 id="_4-2-框架笔记怎么记-重点" tabindex="-1">4.2 框架笔记怎么记（重点） <a class="header-anchor" href="#_4-2-框架笔记怎么记-重点" aria-label="Permalink to &quot;4.2 框架笔记怎么记（重点）&quot;">​</a></h3><p>框架笔记记的不是内容，是<strong>结构 + 易混点</strong>。判断标准只有一条：<strong>考前两周能不能只靠这本笔记回忆出全部考点。</strong></p><p><strong>三遍法</strong>（计划里已经留好了位置，不用额外找时间）：</p><table tabindex="0"><thead><tr><th>遍次</th><th>什么时候</th><th>记什么</th></tr></thead><tbody><tr><td>第 1 遍</td><td>听课中</td><td>只记骨架：一二级标题 + 老师反复强调「必考」的 + 听不懂的（打问号）</td></tr><tr><td>第 2 遍</td><td>当天教材精读后</td><td><strong>合上书默写骨架</strong>，写不出来的回去查，用红笔补</td></tr><tr><td>第 3 遍</td><td>晚上错题复盘</td><td>错题暴露的知识点，回填到笔记对应位置的空白处</td></tr></tbody></table><p>第 2 遍是关键。<strong>默写比抄写有用十倍</strong>——听课当场把老师的话抄下来，那叫记录，不叫记忆。</p><p><strong>记什么：</strong></p><ul><li>一、二、三级标题（骨架本身）</li><li><strong>数字和并列项</strong>——这是多选题的命门（「三大规律」「五对范畴」「四个全面」）</li><li>易混概念的对比</li><li>老师强调的必考点</li><li>自己的问号</li></ul><p><strong>不记什么：</strong></p><ul><li>老师的原话、段子、举例（例子最多写三个字关键词）</li><li>课件上的完整段落</li><li>一眼就懂、不看也不会忘的东西</li></ul><p><strong>每条只写三样</strong>：是什么（关键词，不写完整句）+ 怎么考 + 和谁容易混。 颜色分开：<strong>黑笔骨架，蓝笔考法，红笔只标错过的和易混的。</strong></p><p><strong>长什么样——以马原为例：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>政治 · 马原                                    P.1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>一、唯物论</span></span>
<span class="line"><span>   物质：唯一特性＝客观实在性          ⚠️ ≠ 物质的具体形态</span></span>
<span class="line"><span>   意识：来源物质、内容客观、形式主观</span></span>
<span class="line"><span>   规律：客观性 + 可利用性</span></span>
<span class="line"><span>   ▸ 多选爱考「意识的形式是主观的」对不对</span></span>
<span class="line"><span></span></span>
<span class="line"><span>二、辩证法  ★必考</span></span>
<span class="line"><span>   2 大特征：联系（普遍/客观/多样）、发展（实质＝新事物产生）</span></span>
<span class="line"><span>   3 大规律：对立统一（实质与核心）、质量互变、否定之否定</span></span>
<span class="line"><span>   5 对范畴：原因结果 / 必然偶然 / 可能现实 / 现象本质 / 内容形式</span></span>
<span class="line"><span>   ▸ 数字记死：2、3、5 ← 多选题直接考这个</span></span>
<span class="line"><span>   ⚠️ 主要矛盾 vs 矛盾的主要方面</span></span>
<span class="line"><span>      主要矛盾 → 办事情抓重点</span></span>
<span class="line"><span>      主要方面 → 看问题抓主流</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三、认识论</span></span>
<span class="line"><span>   实践 → 认识 → 再实践（实践是来源/动力/目的/检验标准）</span></span>
<span class="line"><span>   真理：客观性、绝对性、相对性</span></span>
<span class="line"><span></span></span>
<span class="line"><span>四、唯物史观</span></span>
<span class="line"><span>   社会存在 决定 社会意识（社会意识有相对独立性）</span></span>
<span class="line"><span>   生产力 决定 生产关系；经济基础 决定 上层建筑</span></span></code></pre></div><p>一个板块一页，密度就是这样。</p><p><strong>法律板块要单独开「对比页」</strong>——法律部分有一大批长得像的概念，写文字一定混，必须拉表：</p><table tabindex="0"><thead><tr><th>对比</th><th>关键区别</th></tr></thead><tbody><tr><td>行政处罚 / 行政处分</td><td>对象是外部相对人 / 内部人员</td></tr><tr><td>正当防卫 / 紧急避险</td><td>针对不法侵害人 / 针对第三方</td></tr><tr><td>全国人大 / 人大常委会 职权</td><td>修改宪法、选举主席 → 人大；解释宪法、决定特赦 → 常委会</td></tr></tbody></table><p><strong>物理规格</strong>：</p><ul><li><strong>A4 活页本</strong>（能往里面插页，错题补页不用硬塞）</li><li>每个板块夹彩色隔页纸，扉页写目录 + 页码，做到 3 分钟翻到任意板块</li><li><strong>每页左侧留 1/3 空白</strong>，专门用来第 3 遍回填错题</li><li>手写。手写本身就是一遍记忆，而且考场上要手写 1000 字，平时就用手感</li></ul><p><strong>两条边界</strong>：时政不进框架笔记（时政是流水性的，单独一份跟着马克走）；笔记不追求好看，可以缩写、画箭头、用自己的黑话。</p><h3 id="_4-3-教材和刷题怎么配合" tabindex="-1">4.3 教材和刷题怎么配合 <a class="header-anchor" href="#_4-3-教材和刷题怎么配合" aria-label="Permalink to &quot;4.3 教材和刷题怎么配合&quot;">​</a></h3><p>顺序固定：<strong>听课 → 精读教材对应章节 → 立刻做该章节的题</strong>。</p><ul><li>「精读」不是从第一页读到最后一页。先看这一章的目录，问自己「这章有几节、每节几个考点」，再进去读</li><li>教材的作用是<strong>补充老师没讲到的</strong>和<strong>查证</strong>，不是通读一遍</li><li><strong>每章做完题才算这一章结束</strong>。光看完不做题等于没学</li><li>教材上有、课上没讲的，补进框架笔记</li></ul><h3 id="_4-4-刷题怎么做才算有效" tabindex="-1">4.4 刷题怎么做才算有效 <a class="header-anchor" href="#_4-4-刷题怎么做才算有效" aria-label="Permalink to &quot;4.4 刷题怎么做才算有效&quot;">​</a></h3><p>核心动作：<strong>把每道题分成三类</strong>。</p><table tabindex="0"><thead><tr><th>类别</th><th>怎么处理</th></tr></thead><tbody><tr><td>A 类：确定会的</td><td>不写解析，但要记时间。<strong>超过 1 分钟的题要研究怎么更快</strong></td></tr><tr><td>B 类：蒙对 / 犹豫后选对的</td><td><strong>这类最危险，必须当错题处理</strong></td></tr><tr><td>C 类：不会的</td><td>重点分析</td></tr></tbody></table><p>很多人刷题的误区是只看对错，结果 B 类题一直蒙混过关，考场上就露馅。<strong>蒙对的题和做错的题一样值钱。</strong></p><p>每道 B / C 类题问自己三个问题：</p><ol><li>我为什么错？（知识点没记住 / 概念混了 / 审题错 / 计算错 / 时间不够）</li><li>正确思路的第一步是什么？</li><li>下次遇到同类题，靠什么信号识别？</li></ol><p>**刷题量的意义在于「见过足够多的考法」，不是「做够多少题」。**同一类题做 5 道会了，就换下一类，不要盲目刷 1000 道同类的题。每个模块练到「看到题就知道它在考什么」就够了。</p><h3 id="_4-5-错题本怎么记" tabindex="-1">4.5 错题本怎么记 <a class="header-anchor" href="#_4-5-错题本怎么记" aria-label="Permalink to &quot;4.5 错题本怎么记&quot;">​</a></h3><table tabindex="0"><thead><tr><th>科目</th><th>记什么</th><th>不记什么</th></tr></thead><tbody><tr><td>公基</td><td>知识点 + 我为什么错</td><td>不抄题干</td></tr><tr><td>职测</td><td>题型 + 方法要点 + 实际耗时 + <strong>题源（哪套卷第几题）</strong></td><td>不抄整道题</td></tr></tbody></table><p>职测要记题源，因为重做时要回原卷做。</p><p><strong>重做节奏</strong>：</p><ul><li>每周日重做本周错题</li><li>每月末重做本月错题</li><li><strong>考前两周只看错题本</strong>，不做新题</li></ul><p><strong>重做时先看题号别看答案</strong>，做对了打钩，<strong>连续两次做对才划掉</strong>。</p><p>错题本不要抄成摘抄本。它的价值在于「同一类错误不再犯第二次」。</p><h3 id="_4-6-资料分析怎么练-提分最快-必须主攻" tabindex="-1">4.6 资料分析怎么练（提分最快，必须主攻） <a class="header-anchor" href="#_4-6-资料分析怎么练-提分最快-必须主攻" aria-label="Permalink to &quot;4.6 资料分析怎么练（提分最快，必须主攻）&quot;">​</a></h3><p><strong>目标：15 题 22 分钟内做完，正确率 90%。</strong></p><p>分四步练：</p><p>**第一步：背公式。**增长量、增长率、比重、平均数、倍数、基期现期。<strong>要能默写出来</strong>，公式不熟就一定慢。</p><p><strong>第二步：练速算。</strong></p><ul><li>截位直除（分母保留前三位）</li><li><strong>百化分</strong>：1/2 到 1/20 的分数 ↔ 百分数互换表要背下来，看到 12.5% 要条件反射想到 1/8</li><li>估算：选项差距大就粗算，差距小才精算</li></ul><p>**第三步：练「先看选项再算」。**看一眼选项的差距，决定这题用什么精度算。这一步能省掉一半时间。</p><p>**第四步：限时。**每天 3 篇（15 题）限时练，记录用时。不限时的练习等于没练。</p><p><strong>常见陷阱（都会被考）</strong>：</p><ul><li>时间：问的是今年还是去年、是同比还是环比</li><li>单位：万 / 亿、<strong>百分数 / 百分点</strong>（这两个的差别必考）</li><li>范围：全国还是某省、是总量还是其中一部分</li></ul><h3 id="_4-7-图形推理和数字推理怎么练-河南特色-别的地方不考" tabindex="-1">4.7 图形推理和数字推理怎么练（河南特色，别的地方不考） <a class="header-anchor" href="#_4-7-图形推理和数字推理怎么练-河南特色-别的地方不考" aria-label="Permalink to &quot;4.7 图形推理和数字推理怎么练（河南特色，别的地方不考）&quot;">​</a></h3><p><strong>图形推理的解题顺序</strong>（背下来，考场照着走）：</p><ol><li><strong>元素相同</strong> → 看位置（平移、旋转、翻转）</li><li><strong>元素相似</strong> → 看样式（加减同异、黑白运算）</li><li><strong>元素不同</strong> → 先看属性（对称、曲直、开闭），再看数量（点、线、面、角、素）</li><li><strong>立体图</strong> → 空间折叠（相对面、相邻面、箭头法）</li></ol><p>练法：每天 10 题，<strong>重点练「3 秒内判断该用哪条规律」</strong>，而不是算出来。</p><p><strong>数字推理的六种规律</strong>（先判断类型，再算）：</p><table tabindex="0"><thead><tr><th>数列特征</th><th>用什么方法</th></tr></thead><tbody><tr><td>增幅平稳</td><td>作差</td></tr><tr><td>波动小</td><td>作和</td></tr><tr><td>倍数明显</td><td>作商</td></tr><tr><td>增幅大（2 倍以上）</td><td>作积</td></tr><tr><td>多次方附近</td><td>幂次修正</td></tr><tr><td>小数 / 多位数</td><td>拆项、分组</td></tr></tbody></table><p>练法：每天 5 题，练到看一眼就能说出「这是作差型的」。</p><h3 id="_4-8-数量关系怎么取舍" tabindex="-1">4.8 数量关系怎么取舍 <a class="header-anchor" href="#_4-8-数量关系怎么取舍" aria-label="Permalink to &quot;4.8 数量关系怎么取舍&quot;">​</a></h3><p>15 题里只做 2—3 题。</p><ul><li><strong>必做</strong>：和差倍比、工程、利润、年龄、容斥、代入排除</li><li><strong>直接放弃</strong>：复杂行程、排列组合、概率、几何计算</li><li>优先选<strong>题干短、数据只有 3—5 个</strong>的题</li><li>剩下的统一蒙「出现次数最少的选项」</li></ul><p>练法：每天 10 道基础题，只练上面那几类，练熟到 90 秒内解决。</p><h3 id="_4-9-公基客观题怎么记" tabindex="-1">4.9 公基客观题怎么记 <a class="header-anchor" href="#_4-9-公基客观题怎么记" aria-label="Permalink to &quot;4.9 公基客观题怎么记&quot;">​</a></h3><p><strong>关键认知：客观题考的是「辨析」，不是「默写」。</strong></p><p>考试不会直接问你「什么是 XX」，它问的是「下列属于 / 不属于 XX 的是」「关于 XX 说法正确的是」。所以记的时候重点是三样：</p><ol><li><strong>数字和并列项</strong>（三大、四个、五对）——多选题就考项全不全</li><li><strong>易混概念的差别</strong></li><li><strong>常见错误说法</strong>（把 A 的特征安到 B 上）</li></ol><p>**方法：自己出题。**看一个知识点，问自己「这地方能怎么出题骗我」。能问出三个坑，这个点就算记住了。</p><ul><li><strong>政治部分</strong>：抓关键词，不背长句。按「是什么 + 为什么 + 怎么做」的层次记</li><li><strong>法律部分</strong>：<strong>法条要精确</strong>。年龄、期限、金额这些数字必须记死</li><li><strong>公文部分</strong>：文种适用范围、格式要素，一律做表</li></ul><h3 id="_4-10-大作文怎么练" tabindex="-1">4.10 大作文怎么练 <a class="header-anchor" href="#_4-10-大作文怎么练" aria-label="Permalink to &quot;4.10 大作文怎么练&quot;">​</a></h3><p><strong>完整流程（每篇都按这个走）：</strong></p><p><strong>第 1 步 审题（5 分钟）</strong></p><ul><li>题目给的是话题还是观点？</li><li>材料有几则？共同指向什么？</li><li>划出材料里的关键词</li><li>用一句话确定「我要论证什么」</li></ul><p><strong>第 2 步 拟提纲（5 分钟）</strong></p><ul><li>中心论点一句话</li><li>三个分论点。<strong>并列式最稳</strong>：「是什么 / 为什么 / 怎么做」，或者三个并列角度</li><li>每个分论点配一个道理 + 一个例子</li></ul><p><strong>第 3 步 写作（40 分钟，1000 字）</strong></p><ul><li>开头 150 字：引出话题 + 亮明观点（<strong>第一段必须出现中心论点</strong>）</li><li>主体三段，每段 250 字：<strong>段首句就是分论点</strong>，然后解释 + 举例 + 回扣分论点</li><li>结尾 100 字：总结 + 落到「我该怎么做」，不要喊口号</li></ul><p><strong>第 4 步 自评</strong> 对照范文只看三件事：立意准不准、结构全不全、字数时间达不达标。</p><p><strong>无材料作文怎么办：</strong> 从题目关键词发散，用公基的知识（马原哲学、时政）做支撑，例子用近年的（脱贫攻坚、乡村振兴、数字经济、人工智能）。</p><p><strong>素材怎么攒：</strong></p><ul><li>每周 3—5 条，按主题归类</li><li>每条只记两样：<strong>一句话观点 + 一个案例</strong>（人物 / 事件 + 结果）</li><li>例子要能一例多用——比如脱贫攻坚的例子可以用在「奋斗」「人民至上」「基层治理」三个主题上</li></ul><p>**核心提示：作文的分不在文采，在「立意准不准 + 结构清不清」。**1000 字要有 3 个明确的分论点，让阅卷老师 30 秒能看出你的结构。</p><h3 id="_4-11-公文改错怎么练" tabindex="-1">4.11 公文改错怎么练 <a class="header-anchor" href="#_4-11-公文改错怎么练" aria-label="Permalink to &quot;4.11 公文改错怎么练&quot;">​</a></h3><p><strong>三种形式分别怎么找错：</strong></p><p><strong>A. 病句 / 错别字判断改错（2024 年考法）</strong></p><ul><li>错别字：常见成语写错（共度难关 → 共渡难关、风声水起 → 风生水起）</li><li>病句：语序不当、搭配不当、成分残缺、重复啰嗦、前后矛盾</li><li>练法：积累一张常见错字错词表；每句先判断「有没有错」，再想「错在哪」</li></ul><p><strong>B. 公文格式改错（2025 年考法）</strong></p><p>按顺序对照检查清单：</p><ul><li><strong>版头</strong>：发文机关标志、发文字号（年份用六角括号〔〕、序号不加「第」不加 0）、签发人（只有上行文才有）</li><li><strong>主体</strong>：标题（发文机关 + 事由 + 文种）、主送机关、正文、附件说明、发文机关署名、成文日期、印章</li><li><strong>版记</strong>：抄送机关、印发机关和印发日期</li><li>常见错误：文种用错（请示 / 报告混用）、一文多事、越级行文、主送机关错</li></ul><p><strong>C. 公文逻辑改错（2026 年考法）</strong> 题干明说「无格式错误」，所以只找：前后矛盾、因果不当、层次混乱、时间顺序错、数据前后不一致。</p><p><strong>练法</strong>：每周 2 篇，三种轮换。准备一张「公文格式要素对照表」贴在笔记本上，练的时候照着查。</p><h3 id="_4-12-时政怎么跟" tabindex="-1">4.12 时政怎么跟 <a class="header-anchor" href="#_4-12-时政怎么跟" aria-label="Permalink to &quot;4.12 时政怎么跟&quot;">​</a></h3><ul><li><strong>不要背新闻</strong>，要记「是什么 + 定位 / 意义」</li><li>范围：近一年，<strong>近半年是重点</strong></li><li>来源：马克的月度梳理（B站）打底，半月谈《时政提分宝》管考前预测</li><li>重点关注：重要会议（两会、中央经济工作会议、党的全会）、重要文件、领导人重要讲话、重大成就、重要纪念日</li><li><strong>每个事件按六要素拆</strong>：时间、地点、人物、会议/文件名称、主题、数字</li><li>出题点就藏在：<strong>并列词组</strong>（「两不愁三保障」具体指什么）、<strong>关键词</strong>（「基础/关键/核心/首位/主线」）、纪念日、数据</li><li><strong>时政要滚动复习</strong>：平时只做考点化归档（每周 30—60 分钟），<strong>考前 1—2 周集中突击</strong>。太早背时政会大量过期作废</li></ul><h3 id="_4-13-模考和复盘怎么做" tabindex="-1">4.13 模考和复盘怎么做 <a class="header-anchor" href="#_4-13-模考和复盘怎么做" aria-label="Permalink to &quot;4.13 模考和复盘怎么做&quot;">​</a></h3><p><strong>模考（每月最后一个周日）</strong></p><ul><li>全真：上午职测 90 分钟，下午公基 90 分钟，中间按真实考试间隔</li><li>手机闹钟计时，<strong>不查资料、不中途对答案</strong></li><li>用答题卡涂卡，练涂卡时间</li><li>作文必须手写完整，不能只写提纲</li></ul><p><strong>模考后复盘（比考试本身更重要）</strong></p><ol><li>算分：职测、公基各多少，离目标差多少</li><li><strong>失分原因分类</strong>：知识不会 / 记混了 / 时间不够 / 审题错 / 计算错</li><li>统计各模块正确率，找出最弱的一块</li><li>错题写进错题本</li><li>定下周的调整方案</li></ol><p><strong>每日复盘（19:00—20:00）</strong></p><ul><li>今天错了哪些题、为什么错</li><li>有没有知识点要补进框架笔记</li><li>明天的重点是什么</li></ul><h3 id="_4-14-怎么记住-记忆方法与复习节奏" tabindex="-1">4.14 怎么记住（记忆方法与复习节奏） <a class="header-anchor" href="#_4-14-怎么记住-记忆方法与复习节奏" aria-label="Permalink to &quot;4.14 怎么记住（记忆方法与复习节奏）&quot;">​</a></h3><p><strong>核心结论：反复看书几乎没用，主动回忆才有用。</strong></p><p>认知心理学的权威评级（Dunlosky 等 2013，汇总 61 年研究）把学习方式分成两类：</p><table tabindex="0"><thead><tr><th>高效用</th><th>低效用</th></tr></thead><tbody><tr><td><strong>练习测试</strong>（做题、默写）</td><td>反复阅读</td></tr><tr><td><strong>分散练习</strong>（间隔重复）</td><td>划线</td></tr><tr><td></td><td>摘抄总结</td></tr></tbody></table><p>也就是说，<strong>「感觉看懂了」和「考试时能想起来」是两件事</strong>。合上书默写一遍，胜过重读五遍。</p><p><strong>每个知识块的复习时间表</strong></p><p>以「10 月 8 日学完唯物辩证法三大规律」为例：</p><table tabindex="0"><thead><tr><th>节点</th><th>时间</th><th>方式</th></tr></thead><tbody><tr><td>1</td><td>学完 5—10 分钟</td><td>合书口述：刚才这节讲了什么</td></tr><tr><td>2</td><td>学完 30 分钟</td><td>白纸上默写框架，写不出的做标记</td></tr><tr><td>3</td><td>当天睡前</td><td>只看标记处，自问自答</td></tr><tr><td>4</td><td>次日</td><td>默写清单 + 做 10 道对应真题</td></tr><tr><td>5</td><td>第 3—4 天</td><td>重做错题；易混概念做对比表</td></tr><tr><td>6</td><td>第 7 天</td><td>画思维导图，与教材核对</td></tr><tr><td>7</td><td>第 15 天</td><td>清单回忆（三大规律＝？），限时</td></tr><tr><td>8</td><td>第 30 天</td><td>做套题检验</td></tr><tr><td>9</td><td>考前 1—2 周</td><td>快速过易漏项、易混项清单</td></tr></tbody></table><p><strong>每天先清「到期复习」，再学新知识。宁可少学新，不可欠复习。</strong></p><p><strong>学新 : 复习 的时间比例</strong></p><table tabindex="0"><thead><tr><th>阶段</th><th>比例</th></tr></thead><tbody><tr><td>基础期</td><td>1 : 1</td></tr><tr><td>强化期</td><td>1 : 1.5</td></tr><tr><td>冲刺期</td><td>1 : 2 到 1 : 3</td></tr></tbody></table><p>一套知识需要<strong>不同形式的接触 4—6 次</strong>（不是「看 6 遍书」），其中至少 2 次必须是主动提取（默写 / 做题 / 讲）。</p><p><strong>口诀怎么用</strong></p><p>李梦娇的口诀长这样（华图官方讲义实例）：</p><ul><li>三大规律「<strong>互否对</strong>」——对立统一、质量互变、否定之否定</li><li>行政处分「<strong>六板斧，警告两过降撤除</strong>」——警告、记过、记大过、降级、撤职、开除</li><li>刑罚「主刑<strong>管拘有无死</strong>，副刑<strong>罚剥没收逐</strong>」</li><li>未遂是「<strong>欲达目的而不能</strong>」，中止是「<strong>能达目的而不欲</strong>」</li><li>生产要素「劳资技管」（谐音：老子机关）</li></ul><p><strong>自编口诀四法</strong>：首字缩略、谐音化、生活比喻、数字编码。 自编流程：理解内容 → 列出所有项 → 数清数量 → 抽首字 → 读顺 → 不顺就换谐音加画面 → <strong>回头检查能否只靠口诀把每一项还原出来</strong>。</p><p><strong>口诀的边界（很重要）</strong>：它只是提取线索，必须走「<strong>口诀 → 还原全部项 → 真题验证</strong>」三步闭环。只背「六板斧」却认不出「罚款不是行政处分」，等于白背——而这恰恰是多选题的坑。口诀只给最容易混、最常考、最难记的清单编，<strong>不超过考点的 10—15%</strong>。</p><p><strong>什么必须死记、什么理解即可</strong></p><table tabindex="0"><thead><tr><th>必须死记</th><th>理解即可（+会用）</th></tr></thead><tbody><tr><td>并列清单（几个全面、几种处分）</td><td>马原原理</td></tr><tr><td>数字（年龄、期限、比例、金额）</td><td>经济供求、货币政策逻辑</td></tr><tr><td>专有名词与对应（会议名、人物-成就）</td><td>管理学原理</td></tr><tr><td>公文文种与格式要素</td><td>法律构成要件的推理</td></tr><tr><td>时政细节</td><td></td></tr></tbody></table><p><strong>怎么判断某个考点属于哪类</strong>：做 3 年真题。反复以「原话挖空」出现的 → 死记；总是「给情境选原理/判断对错」的 → 理解 + 辨析。</p><p><strong>睡眠与时段</strong></p><ul><li>上午精力最好的 2 小时背最硬的内容（法律、政治、需要精确提取的清单）</li><li>下午做题（输出型任务）</li><li><strong>睡前 30—60 分钟过一遍当天最难记的清单</strong>——睡眠会巩固记忆</li><li>起床后 10—20 分钟先回忆昨晚内容，再看书</li><li>每天睡 7—8 小时；午休 20—30 分钟（不超过 40 分钟，避免深睡后昏沉）</li></ul><h3 id="_4-15-多选题怎么答-评分规则决定策略" tabindex="-1">4.15 多选题怎么答（评分规则决定策略） <a class="header-anchor" href="#_4-15-多选题怎么答-评分规则决定策略" aria-label="Permalink to &quot;4.15 多选题怎么答（评分规则决定策略）&quot;">​</a></h3><p><strong>这条会影响你的答题动作，先说结论：多选题没有「保守作答」这回事。</strong></p><p>官方公告和大纲<strong>都没有写</strong>评分细则。河南省内事业单位试卷的通行写法是「<strong>多选、少选、错选均不得分</strong>」。</p><p>按这个规则，策略很清楚：<strong>对每个选项独立判断</strong>。少选和错选一样都是 0 分，所以拿不准的选项，<strong>只要你觉得它对的可能性过半就选</strong>——漏掉一个正确选项必然 0 分，选上还有机会。</p><blockquote><p>考前以试卷首页「注意事项」写的为准。如果那上面写了「少选得部分分」，再改成保守策略。</p></blockquote><p><strong>针对多选题的记忆法</strong>：</p><ol><li><strong>封闭清单卡</strong>：每学一个 N 项考点，立刻记成「数量 + N 项内容」。回忆时先答「几个」，再逐项背，最后数一遍</li><li><strong>互为干扰项对比</strong>：把相近清单并排写（行政处罚 7 类 vs 行政处分 6 种 vs 刑罚 9 种），只背差异点</li><li><strong>错题只记一件事</strong>：这次是「漏了第几项」还是「把哪个项混进来了」</li><li><strong>考前易漏项清单</strong>：把三个月所有漏过的项汇总成一页，反复看</li></ol><h2 id="五、报名、选岗与专业匹配" tabindex="-1">五、报名、选岗与专业匹配 <a class="header-anchor" href="#五、报名、选岗与专业匹配" aria-label="Permalink to &quot;五、报名、选岗与专业匹配&quot;">​</a></h2><h3 id="_5-1-计算机科学与技术-080901-能报哪些岗位" tabindex="-1">5.1 计算机科学与技术（080901）能报哪些岗位 <a class="header-anchor" href="#_5-1-计算机科学与技术-080901-能报哪些岗位" aria-label="Permalink to &quot;5.1 计算机科学与技术（080901）能报哪些岗位&quot;">​</a></h3><p>岗位表「专业」栏有七八种写法，能不能报差别很大。以 2026 年商丘的真实岗位表为例：</p><table tabindex="0"><thead><tr><th>岗位写法</th><th>080901 能报吗</th><th>说明</th></tr></thead><tbody><tr><td>不限专业</td><td>✅</td><td>2026 年商丘有 89 个</td></tr><tr><td>计算机类（0809）</td><td>✅</td><td>专业类包含关系，官方明确</td></tr><tr><td>计算机科学与技术（080901）</td><td>✅</td><td>精确列出</td></tr><tr><td>工学（08）</td><td>✅</td><td>门类包含，2026 年省直有 6 个</td></tr><tr><td><strong>电子信息类（0807）</strong></td><td>❌</td><td>0807 与 0809 是并列的两个专业类</td></tr><tr><td><strong>只列「软件工程（080902）」「网络工程（080903）」</strong></td><td>❌</td><td>同班同学的专业 ≠ 你的专业</td></tr><tr><td><strong>数据科学与大数据技术（080910T）单独列</strong></td><td>❌</td><td>同上</td></tr><tr><td><strong>计算机科学与技术（0812）</strong></td><td>❌</td><td>0812 是研究生代码，这类岗位要硕士</td></tr><tr><td><strong>计算机类（5102）</strong></td><td>❌</td><td>5102 是高职专科代码</td></tr><tr><td>信息与计算科学（070102）</td><td>❌</td><td>属数学类，理学</td></tr><tr><td>信息管理与信息系统（120102）</td><td>❌</td><td>属管理科学与工程类，管理学</td></tr></tbody></table><p>官方判定依据是国家目录（《普通高等学校本科专业目录》），官方原文原则是「<strong>专业要求为专业类的，该专业类所包含的具体专业均符合要求</strong>」。河南联考<strong>没有</strong>自己的专业指导目录——河南省考公务员的那个专业目录<strong>不适用于</strong>事业单位联考。</p><p>2026 年商丘 1002 个岗位里，计科本科可报 <strong>115 个</strong>，其中综合类 <strong>105 个</strong>，占综合类 485 个的约 21.7%。</p><blockquote><p>同一个数字在两套目录里含义不同：<strong>0809 在本科目录是「计算机类」，在研究生目录是「电子科学与技术」</strong>。只看数字会误判。</p></blockquote><h3 id="_5-2-三个致命的操作细节" tabindex="-1">5.2 三个致命的操作细节 <a class="header-anchor" href="#_5-2-三个致命的操作细节" aria-label="Permalink to &quot;5.2 三个致命的操作细节&quot;">​</a></h3><p><strong>第一，报名系统初审不查专业。<strong>系统只查信息是否齐全、格式对不对，提交成功就算「通过初审」——但官方明确写了「<strong>报名系统初审通过不代表报考者符合报考岗位资格条件</strong>」。真正的专业审核在</strong>面试前的资格审查</strong>，那时发现不符会直接取消面试资格。所以<strong>报名前一定要打岗位表「备注」栏里的咨询电话逐个确认专业</strong>。</p><p><strong>第二，一人一岗，提交即锁定。<strong>每名报考人员限报一个岗位，初审通过后不能改报、不能改信息。唯一的改报机会是报考岗位</strong>被取消</strong>之后（2026 年是 5 月 8 日 9:00—17:00，只有 8 小时）。</p><p><strong>第三，「其他条件」栏藏着门槛。<strong>2026 年商丘有 101 个岗位要求中共党员（含预备党员，预备党员也算）；纪检监察系统的岗位有近亲属回避要求；有的岗位要求适应夜班、经常出差或野外作业。 好消息是商丘 2026 年</strong>没有</strong>户籍、性别、双一流、工作经历的限制（省直有岗位要求 5 年最低服务年限，商丘没有）。</p><h3 id="_5-3-岗位表怎么筛" tabindex="-1">5.3 岗位表怎么筛 <a class="header-anchor" href="#_5-3-岗位表怎么筛" aria-label="Permalink to &quot;5.3 岗位表怎么筛&quot;">​</a></h3><p>岗位表是 Excel（商丘版 13 列：地市名称｜主管单位｜招聘单位｜经费供给形式｜岗位类别及等级｜岗位代码｜考试类别｜招聘人数｜专业（学科）及专业代码｜学历学位｜其他条件｜备注）。</p><p>实操步骤：</p><ol><li>打开 Excel，选中表头 → 数据 → 筛选（Ctrl+Shift+L）</li><li>筛「考试类别」= 综合类</li><li>筛「学历学位」包含「本科」</li><li>在「专业」列分别搜：<strong>「不限专业」→「计算机类」→「0809」→「080901」</strong>，把结果并起来</li><li><strong>务必同时搜全角和半角的括号</strong>：<code>（0809）</code> 和 <code>(0809)</code> 都要搜</li><li>用「其他条件」做排除法，把要求党员、资格证的先剔除或单独标记</li><li>用「备注」列看工作地点和咨询电话，逐岗打电话确认专业</li><li>岗位代码是 10 位，<strong>前 2 位是考区</strong>（商丘 = 13 开头，省直 = 18 开头）</li></ol><h3 id="_5-4-报名时间线-2026-年实际-2027-年参照" tabindex="-1">5.4 报名时间线（2026 年实际，2027 年参照） <a class="header-anchor" href="#_5-4-报名时间线-2026-年实际-2027-年参照" aria-label="Permalink to &quot;5.4 报名时间线（2026 年实际，2027 年参照）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>节点</th><th>2026 年实际</th></tr></thead><tbody><tr><td>公告 + 岗位表发布</td><td>4 月 22 日</td></tr><tr><td><strong>网上报名</strong></td><td>4 月 24 日 9:00 — 4 月 30 日 17:00（7 天）</td></tr><tr><td>网上缴费</td><td>4 月 25 日 — 5 月 1 日（<strong>每人每科 30 元，综合类 2 科 = 60 元</strong>）</td></tr><tr><td>核减 / 取消岗位公告</td><td>5 月 7 日</td></tr><tr><td><strong>被取消岗位改报</strong></td><td><strong>5 月 8 日 9:00—17:00（只有 8 小时）</strong></td></tr><tr><td>打印准考证</td><td>5 月 25 日 — 5 月 30 日</td></tr><tr><td>笔试</td><td>5 月 30 日</td></tr><tr><td>加分资格审核</td><td>6 月 1 日 — 6 月 3 日</td></tr></tbody></table><p>报名入口：<strong>河南省人事考试中心网站 www.hnrsks.com</strong>；商丘的公告和岗位表在<strong>商丘人事考试网 www.sqrsks.cn</strong>。</p><p><strong>报名时机</strong>：官方明确提示过「部分考生持观望心态导致报名集中在最后一天，造成网络拥堵，建议及早完成」。<strong>不要为了看报名人数拖到最后一天</strong>——提交后就不能改，而且提前报名才有时间打电话核实专业。</p><p><strong>注意冷门岗位</strong>：缴费人数不足 3:1 会核减或取消（2026 年商丘核减 35 个、取消 74 个岗位）。所以也不能专挑最冷的岗。</p><h3 id="_5-5-加分政策" tabindex="-1">5.5 加分政策 <a class="header-anchor" href="#_5-5-加分政策" aria-label="Permalink to &quot;5.5 加分政策&quot;">​</a></h3><p>只有两类人：<strong>大学生村干部</strong>、<strong>退役大学生士兵</strong>。</p><ul><li>报省、市级单位 <strong>+5 分</strong>；报县、乡镇单位 <strong>+10 分</strong></li><li>加在<strong>笔试总成绩</strong>上</li><li>2026 年是 6 月 1—3 日到用人单位现场审核材料，<strong>逾期视为放弃</strong>，审核后公示 3 天</li></ul><blockquote><p>另外，体检参照的是《公务员录用体检通用标准》，笔试没有全省统一合格线——由各用人单位或地市自行决定是否设最低控制线（2026 年郑州市某岗位设了 40 分）。</p></blockquote><h2 id="六、考场规则" tabindex="-1">六、考场规则 <a class="header-anchor" href="#六、考场规则" aria-label="Permalink to &quot;六、考场规则&quot;">​</a></h2><h3 id="_6-1-考试当天的硬规矩" tabindex="-1">6.1 考试当天的硬规矩 <a class="header-anchor" href="#_6-1-考试当天的硬规矩" aria-label="Permalink to &quot;6.1 考试当天的硬规矩&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>规则</th></tr></thead><tbody><tr><td>到达时间</td><td><strong>建议提前 50 分钟到考点</strong></td></tr><tr><td>迟到</td><td>开考 30 分钟后不得入场</td></tr><tr><td>证件</td><td><strong>准考证 + 有效身份证</strong>。身份证丢了要用临时身份证或派出所开带照片的临时身份证明；<strong>电子身份证、社保卡、驾照、户口簿都不认</strong></td></tr><tr><td>文具</td><td>自备 2B 铅笔、橡皮、黑色水笔</td></tr><tr><td>禁带</td><td><strong>手机、智能手表、电子手环</strong>——无论是否开机使用，带到座位就算违纪；计算器禁止</td></tr><tr><td>答题卡</td><td>按时填涂个人信息；<strong>主观题网络阅卷，必须在指定区域作答，超出区域无效</strong></td></tr></tbody></table><p><strong>这几个动作都会导致成绩无效</strong>：开考前提前答题、结束铃响后继续答题、把试卷 / 答题卡 / 草稿纸带出考场、坐错座位不改、拍照传播试题、与他人答案雷同（无论故意与否）。</p><h3 id="_6-2-一天的节奏" tabindex="-1">6.2 一天的节奏 <a class="header-anchor" href="#_6-2-一天的节奏" aria-label="Permalink to &quot;6.2 一天的节奏&quot;">​</a></h3><ul><li>上午 <strong>9:00—10:30</strong> 职业能力测验</li><li>下午 <strong>14:00—15:30</strong> 公共基础知识</li><li><strong>中间隔 3.5 小时</strong>。官方没有统一安排午休和午餐，需要自己解决——提前踩点找好吃饭和能躺一会儿的地方</li></ul><h2 id="七、每日时间表" tabindex="-1">七、每日时间表 <a class="header-anchor" href="#七、每日时间表" aria-label="Permalink to &quot;七、每日时间表&quot;">​</a></h2><p><strong>基础期（W1–W8，5–6h）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>08:30–10:00  公基听课 + 记框架笔记（第 1 遍）</span></span>
<span class="line"><span>10:00–11:30  教材对应章节 + 章节刷题 + 默写骨架（第 2 遍）</span></span>
<span class="line"><span>11:30–14:00  午饭 + 午休</span></span>
<span class="line"><span>14:00–15:00  职测模块方法论</span></span>
<span class="line"><span>15:00–17:00  职测限时刷题</span></span>
<span class="line"><span>17:00–19:00  晚饭 + 休息（离开书桌）</span></span>
<span class="line"><span>19:00–20:00  错题复盘 + 回填框架笔记（第 3 遍）</span></span>
<span class="line"><span>20:00–20:30  时政</span></span></code></pre></div><p><strong>强化期（W9–W25，6h）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>08:00–11:00  公基二轮专项（听课 / 刷题 / 错题三刷）</span></span>
<span class="line"><span>11:00–14:00  午休</span></span>
<span class="line"><span>14:00–17:30  职测模块刷题 + 限时套卷</span></span>
<span class="line"><span>17:30–19:00  晚饭 + 休息</span></span>
<span class="line"><span>19:00–20:00  作文 或 改错（隔日轮换）</span></span>
<span class="line"><span>20:00–20:30  时政</span></span></code></pre></div><p><strong>冲刺期（W26–W34，6.5–7h）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>08:00–09:40  职测整卷限时（90 分钟）</span></span>
<span class="line"><span>09:50–11:20  公基整卷限时（90 分钟）</span></span>
<span class="line"><span>11:20–14:00  午休</span></span>
<span class="line"><span>14:00–17:00  对答案 + 逐题精析 + 错题归因</span></span>
<span class="line"><span>17:00–19:00  休息</span></span>
<span class="line"><span>19:00–20:00  时政冲刺 / 作文主题打磨</span></span>
<span class="line"><span>20:00–20:30  素材库整理</span></span></code></pre></div><p><strong>每天第一件事是先清「到期复习」，再学新的。</strong></p><h2 id="八、每周固定动作" tabindex="-1">八、每周固定动作 <a class="header-anchor" href="#八、每周固定动作" aria-label="Permalink to &quot;八、每周固定动作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>动作</th></tr></thead><tbody><tr><td>周六 19:00–20:00</td><td><strong>手写大作文 1 篇，限时 50 分钟，1000 字</strong></td></tr><tr><td>周日上午</td><td>公文改错 2 篇（三种形式轮换）+ 本周错题重做</td></tr><tr><td>周日下午</td><td><strong>完全休息</strong></td></tr><tr><td>周日晚上</td><td>下周计划 + 素材库整理 + 作文自评</td></tr><tr><td>每月最后一个周日</td><td>全真模拟：上午职测 90 分钟，下午公基 90 分钟</td></tr></tbody></table><p>留半天「回炉日」只做错题和上周清单，不学新内容。</p><h2 id="九、34-周逐周计划" tabindex="-1">九、34 周逐周计划 <a class="header-anchor" href="#九、34-周逐周计划" aria-label="Permalink to &quot;九、34 周逐周计划&quot;">​</a></h2><h3 id="基础期-w1–w8-10-5–11-29" tabindex="-1">基础期（W1–W8，10/5–11/29） <a class="header-anchor" href="#基础期-w1–w8-10-5–11-29" aria-label="Permalink to &quot;基础期（W1–W8，10/5–11/29）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周</th><th>日期</th><th>公基主攻</th><th>职测主攻</th><th>主观题</th></tr></thead><tbody><tr><td>1</td><td>10/5–10/11</td><td>政治·马原</td><td>言语·逻辑填空</td><td>看作文结构课，拆解范文写提纲</td></tr><tr><td>2</td><td>10/12–10/18</td><td>政治·毛概+中特+习思想</td><td>言语·片段阅读</td><td>改错课 1–6 集；<strong>写第 1 篇完整作文</strong></td></tr><tr><td>3</td><td>10/19–10/25</td><td>政治·时政</td><td>言语·语句表达+限时套题</td><td>作文 1 篇</td></tr><tr><td>4</td><td>10/26–11/1</td><td>法律·宪法+法理+行政法</td><td>判断·图形推理</td><td>作文 1 篇</td></tr><tr><td>5</td><td>11/2–11/8</td><td>法律·民法+刑法</td><td>判断·定义+类比</td><td>作文 1 篇</td></tr><tr><td>6</td><td>11/9–11/15</td><td>法律·诉讼法+公司法</td><td>判断·逻辑判断</td><td>作文 1 篇</td></tr><tr><td>7</td><td>11/16–11/22</td><td>经济·微观+宏观</td><td>资料分析·概念+速算</td><td>作文 1 篇</td></tr><tr><td>8</td><td>11/23–11/29</td><td>公文+职业道德+人文国情</td><td>资料限时+数字推理入门</td><td>作文 1 篇</td></tr></tbody></table><h3 id="强化期-w9–w25-11-30–3-28" tabindex="-1">强化期（W9–W25，11/30–3/28） <a class="header-anchor" href="#强化期-w9–w25-11-30–3-28" aria-label="Permalink to &quot;强化期（W9–W25，11/30–3/28）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周</th><th>日期</th><th>公基二轮</th><th>职测专项</th><th>套卷</th></tr></thead><tbody><tr><td>9</td><td>11/30–12/6</td><td>政治·马原+毛概</td><td>言语（每日 30 题）</td><td>—</td></tr><tr><td>10</td><td>12/7–12/13</td><td>政治·中特+习思想</td><td>言语（每日 30 题）</td><td>—</td></tr><tr><td>11</td><td>12/14–12/20</td><td>政治·时政+错题</td><td>判断·图推加倍</td><td>—</td></tr><tr><td>12</td><td>12/21–12/27</td><td>法律·宪法/行政法</td><td>判断·定义/类比</td><td>—</td></tr><tr><td>13</td><td>12/28–1/3</td><td>法律·民法/刑法</td><td>判断·逻辑</td><td><strong>起：每周 2 套整卷</strong></td></tr><tr><td>14</td><td>1/4–1/10</td><td>法律·诉讼法/公司法</td><td>资料分析（每日 3 篇限时）</td><td>2 套 + <strong>第 1 次人工精批</strong></td></tr><tr><td>15</td><td>1/11–1/17</td><td>经济</td><td>资料·速度攻坚</td><td>2 套</td></tr><tr><td>16</td><td>1/18–1/24</td><td>经济</td><td>数量·高频 6 类</td><td>2 套</td></tr><tr><td>17</td><td>1/25–1/31</td><td>公文·改错实战</td><td>数量·数字推理</td><td>2 套</td></tr><tr><td>18</td><td>2/1–2/7</td><td><strong>春节·降强度</strong>（只跟时政+作文）</td><td>—</td><td>—</td></tr><tr><td>19</td><td>2/8–2/14</td><td>公文收尾 + 人文科技国情</td><td>常识判断 + 弱项</td><td>2 套</td></tr><tr><td>20</td><td>2/15–2/21</td><td>政治+法律 错题三刷</td><td>言语+判断 速度攻坚</td><td>2 套</td></tr><tr><td>21</td><td>2/22–2/28</td><td>政治+法律 错题三刷</td><td>言语+判断 速度攻坚</td><td><strong>起：加每周 1 次全套模拟</strong></td></tr><tr><td>22</td><td>3/1–3/7</td><td>经济+公文 错题三刷</td><td>资料+数量 速度攻坚</td><td>2 套 + 1 模考</td></tr><tr><td>23</td><td>3/8–3/14</td><td>经济+公文 错题三刷</td><td>资料+数量 速度攻坚</td><td>2 套 + 1 模考</td></tr><tr><td>24</td><td>3/15–3/21</td><td>全科串讲</td><td>全科限时套卷</td><td>2 套 + 1 模考</td></tr><tr><td>25</td><td>3/22–3/28</td><td>全科串讲 + 弱点攻坚</td><td>全科限时套卷</td><td>2 套 + 1 模考</td></tr></tbody></table><h3 id="冲刺期-w26–w34-3-29–5-30" tabindex="-1">冲刺期（W26–W34，3/29–5/30） <a class="header-anchor" href="#冲刺期-w26–w34-3-29–5-30" aria-label="Permalink to &quot;冲刺期（W26–W34，3/29–5/30）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周</th><th>日期</th><th>任务</th></tr></thead><tbody><tr><td>26</td><td>3/29–4/4</td><td>近 4 年河南联考真题第一遍（职测+公基各 2 套，全真限时）</td></tr><tr><td>27</td><td>4/5–4/11</td><td>同上 + 逐题精析、错题归因</td></tr><tr><td>28</td><td>4/12–4/18</td><td>同上；<strong>第 2 次人工精批</strong></td></tr><tr><td>29</td><td>4/19–4/25</td><td>邻省真题；<strong>公告预计发布，下载岗位表按 §5.3 筛选</strong></td></tr><tr><td>30</td><td>4/26–5/2</td><td><strong>报名（预计 4/24–4/30）· 选岗 · 打电话确认专业</strong></td></tr><tr><td>31</td><td>5/3–5/9</td><td><strong>盯核减公告（可能 5/7）· 准备改报</strong>；河南真题第二遍（只做错题）</td></tr><tr><td>32</td><td>5/10–5/16</td><td>时政冲刺（近半年过 3 遍）+ 作文押题；<strong>第 3—5 次人工精批</strong></td></tr><tr><td>33</td><td>5/17–5/23</td><td>考前一周：<strong>不做新题</strong>，只看错题本+框架笔记+素材库；打印准考证、踩点</td></tr><tr><td>34</td><td>5/24–5/30</td><td>笔试周。<strong>5/30 考完当天开始练结构化面试</strong></td></tr></tbody></table><blockquote><p>目标：<strong>5 月 15 日前全部准备就绪</strong>，之后都是缓冲。笔试按往年规律落在 5 月中下旬周末（5/20、5/26、5/18、5/30）。</p></blockquote><h2 id="十、检查点" tabindex="-1">十、检查点 <a class="header-anchor" href="#十、检查点" aria-label="Permalink to &quot;十、检查点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查点</th><th>时间</th><th>标准</th><th>没达到怎么办</th></tr></thead><tbody><tr><td>一</td><td>11/29（W8）</td><td>公基过完一遍；作文 ≥7 篇</td><td>用 W9 补，政治三轮压缩 1 周</td></tr><tr><td>二</td><td>3/28（W25）</td><td>整卷模考稳定 65 分</td><td>W26–27 专攻最弱模块，真题量减半</td></tr><tr><td>三</td><td>5/9（W31）</td><td>真题正确率稳定</td><td><strong>放弃数量关系</strong>，全力保其他</td></tr></tbody></table><p>**调整原则：先砍公基的知识输入，绝不砍作文和改错。**那 50 分是从 55 分到 70 分的全部空间。</p><h2 id="十一、笔试之后-面试、体检、考察" tabindex="-1">十一、笔试之后：面试、体检、考察 <a class="header-anchor" href="#十一、笔试之后-面试、体检、考察" aria-label="Permalink to &quot;十一、笔试之后：面试、体检、考察&quot;">​</a></h2><h3 id="_11-1-面试-占总成绩一半-准备时间极短" tabindex="-1">11.1 面试：占总成绩一半，准备时间极短 <a class="header-anchor" href="#_11-1-面试-占总成绩一半-准备时间极短" aria-label="Permalink to &quot;11.1 面试：占总成绩一半，准备时间极短&quot;">​</a></h3><p><strong>形式</strong>：结构化面试。</p><table tabindex="0"><thead><tr><th>地区</th><th>2026 年实际</th></tr></thead><tbody><tr><td>商丘综合类</td><td><strong>10 分钟 3 题，看题，有草稿纸</strong></td></tr><tr><td>省直</td><td>15 分钟 3 题，有题本纸笔</td></tr></tbody></table><ul><li>考官一般 7 人，满分 100 分，体操计分（去掉最高最低分取平均），<strong>当场公布</strong></li><li><strong>没有自我介绍</strong>。只报告面试序号，不得透露姓名、家庭情况</li><li><strong>五大题型</strong>：综合分析（第一题必考）、组织管理、人际沟通、应急应变、岗位匹配</li><li>答题每题控制在 2.5—3 分钟</li></ul><p><strong>真题长什么样</strong>（2026 年 8 月 1 日商丘综合岗）：</p><ol><li>12345 电话工单增多：有人认为顺应时代、承载群众诉求；有人认为增加基层负担、可能无法真正解决问题。你怎么看？</li><li>单位新上线一个软件系统，领导安排你调查使用效果和群众诉求，你会怎么调查？</li><li>有群众在废旧铁路上摔倒住院，家属在留言板投诉要求拆除，铁路权属不明确，领导交你处置，你会怎么收集信息？</li></ol><p><strong>何时开始准备——这是最要紧的一条</strong>：</p><p>2026 年 6 月 24 日出成绩，<strong>7 月 12 日省直就面试（只有 18 天）</strong>，商丘 8 月 1 日面试（约 5 周）。所以：</p><ul><li><strong>笔试考完当天（5/30）就开始准备面试</strong>，不能等成绩</li><li>从 5 月 30 日到 6 月 24 日这段等待期，是最容易被浪费、也最能拉开差距的窗口</li><li>练习方式优先级：<strong>开口录音回听 &gt; 找人当考官掐表模拟 &gt; 对镜练 &gt; 只看不练</strong></li></ul><h3 id="_11-2-体检" tabindex="-1">11.2 体检 <a class="header-anchor" href="#_11-2-体检" aria-label="Permalink to &quot;11.2 体检&quot;">​</a></h3><ul><li>参照《公务员录用体检通用标准》，费用自理（商丘市直 310 元）</li><li><strong>提前 1—2 周去三甲医院按公务员套餐预检</strong>：血压、血常规、尿常规、肝功能（转氨酶）、肾功能、血糖、心电图、腹部 B 超、胸片、视力、甲状腺</li></ul><table tabindex="0"><thead><tr><th>重点盯的指标</th><th>标准 / 注意</th></tr></thead><tbody><tr><td>血压</td><td>&lt; 140/90。紧张容易「白大衣高血压」，可现场深呼吸复测</td></tr><tr><td>转氨酶</td><td>正常 &lt; 40，&gt; 80 危险。熬夜、饮酒、剧烈运动、油腻饮食会一过性升高</td></tr><tr><td>心电图</td><td>异常但排除病理性的合格；病理性异常要当场复检</td></tr><tr><td>视力</td><td>普通岗位双眼矫正视力需 ≥ 4.8</td></tr><tr><td>甲状腺</td><td>三度单纯性甲状腺肿不合格；<strong>单纯桥本甲状腺炎已明确合格</strong>（2025 年 11 月标准调整）</td></tr></tbody></table><ul><li>体检前 3 天清淡饮食、禁酒、不熬夜、不剧烈运动；前 8—12 小时禁食禁水</li><li>有异议可在接到结论 <strong>7 日内</strong>申请复检，<strong>复检只能一次</strong>，以复检结论为准</li><li><strong>不要自行吃降酶药或隐瞒疾病</strong>（查实取消资格）；不要漏检（视同放弃）</li></ul><h3 id="_11-3-考察-政审" tabindex="-1">11.3 考察（政审） <a class="header-anchor" href="#_11-3-考察-政审" aria-label="Permalink to &quot;11.3 考察（政审）&quot;">​</a></h3><p>参照《公务员录用考察办法（试行）》，考察组会到<strong>你所在的学校、居住地社区、户籍地派出所</strong>了解情况、查有无犯罪记录，并查阅档案。主要考察本人——<strong>普通综合类岗位没有核查配偶父母的依据</strong>（法规里只有涉密岗位才考察家庭成员和主要社会关系）。</p><p>需要提交：《考察表》、个人总结、个人征信情况、档案存放单位信息。</p><p><strong>现在就做一件事</strong>：确认自己的档案在学校还是已转回生源地，确保档案里没有缺失材料和处分材料。毕业后不要把档案留在自己手里。</p><h3 id="_11-4-总成绩、并列和递补" tabindex="-1">11.4 总成绩、并列和递补 <a class="header-anchor" href="#_11-4-总成绩、并列和递补" aria-label="Permalink to &quot;11.4 总成绩、并列和递补&quot;">​</a></h3><ul><li><strong>总成绩 = 笔试 × 50% + 面试 × 50%</strong></li><li>并列处理顺序：先比<strong>笔试成绩</strong> → 再比<strong>职业能力测验</strong>成绩 → 还相同就加试一场面试</li><li><strong>递补只有一次机会</strong>，在面试确认环节。此后面试、体检、考察、公示各环节出现空缺，<strong>都不再递补</strong></li></ul><h3 id="_11-5-试用期与待遇" tabindex="-1">11.5 试用期与待遇 <a class="header-anchor" href="#_11-5-试用期与待遇" aria-label="Permalink to &quot;11.5 试用期与待遇&quot;">​</a></h3><ul><li><strong>初次就业且聘用合同 3 年以上的，试用期 12 个月</strong></li><li>商丘 2026 年的公告和岗位表都<strong>没有</strong>最低服务年限要求（以聘用合同为准，签约时要看清条款）</li><li>待遇（考生分享，差异大，仅供参考）：市直转正后月到手约 4000—5500 元；县区年收入约 5—6 万；乡镇月到手 3000 余元。差异主要看文明奖 / 考核奖是否发放和县区财政</li></ul><h2 id="十二、关键日期与硬约束" tabindex="-1">十二、关键日期与硬约束 <a class="header-anchor" href="#十二、关键日期与硬约束" aria-label="Permalink to &quot;十二、关键日期与硬约束&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日期</th><th>事项</th></tr></thead><tbody><tr><td>2026-10-05</td><td>教材到货，W1 启动</td></tr><tr><td>2026-11-06</td><td>教资笔试成绩公布</td></tr><tr><td>2026-11-29</td><td>检查点一</td></tr><tr><td>2027-02-06</td><td>春节（降强度周）</td></tr><tr><td>2027-03-28</td><td>检查点二</td></tr><tr><td>2027-04 中下旬</td><td>联考公告 + 岗位表发布，按 §5.3 筛岗</td></tr><tr><td>2027-04 下旬</td><td>报名（7 天），<strong>打电话确认专业后再提交</strong></td></tr><tr><td>2027-05 上旬</td><td>核减 / 取消岗位公告，<strong>留意 8 小时改报窗口</strong></td></tr><tr><td>2027-05-09</td><td>检查点三</td></tr><tr><td>2027-05 下旬</td><td>打印准考证、踩点、笔试</td></tr><tr><td>2027-05-30（笔试当天）</td><td><strong>开始准备结构化面试</strong></td></tr><tr><td>2027-06 上旬</td><td>加分材料现场审核（如符合条件）</td></tr><tr><td>2027-06 下旬</td><td>出成绩</td></tr><tr><td>2027-07 上旬</td><td>面试确认及资格审查（备齐学历认证、党员证明、同意报考证明）</td></tr><tr><td>2027-07 下旬—8 月</td><td>面试</td></tr><tr><td>2027-08 中下旬</td><td>预检 + 体检</td></tr><tr><td>2027-09</td><td>考察</td></tr></tbody></table><p><strong>毕设硬约束（并行）</strong>：10—12 月完成平台系统主体 → 1 月收尾测试 → 2—3 月论文成稿 → 4 月定稿送审 → <strong>5 月留空给笔试</strong>。</p><p><strong>备选（本轮没过还有牌）</strong>：乡村振兴村级协理员（商丘 800 名）、社区网格协理员（商丘 620 名）、三支一扶（商丘 309 名），全部考职测 + 公基或公共基础知识；河南事业单位不限应届、不限户籍，毕业后两年择业期内可再报。</p>`,228)])])}const c=d(a,[["render",o]]);export{b as __pageData,c as default};
